  `param_id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `param_key` varchar(64) NOT NULL COMMENT '参数键',
  `param_value` int NOT NULL COMMENT '参数值（分钟数）',
  `name` varchar(64) NOT NULL COMMENT '参数名称',
  `description` varchar(255) DEFAULT NULL COMMENT '说明',
  `value_min` int DEFAULT NULL COMMENT '值域下限（含）',
  `value_max` int DEFAULT NULL COMMENT '值域上限（含）',
  `status` char(1) NOT NULL DEFAULT '0' COMMENT '状态：0=正常, 1=停用',
  `create_by` varchar(64) DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` varchar(64) DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `remark` varchar(255) DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`param_id`),
  UNIQUE KEY `uk_param_key` (`param_key`),
  CONSTRAINT `ck_locked_rows` CHECK ((((`param_key` <> _utf8mb4't_econ') or ((`param_value` <=> 5) and (`value_min` <=> 5) and (`value_max` <=> 5))) and ((`param_key` <> _utf8mb4'tier_threshold_fast') or ((`param_value` <=> 1) and (`value_min` <=> 1) and (`value_max` <=> 1))) and ((`param_key` <> _utf8mb4'tier_threshold_econ') or ((`param_value` <=> 5) and (`value_min` <=> 5) and (`value_max` <=> 5))) and ((`param_key` <> _utf8mb4't_fast') or ((`value_min` <=> 1) and (`value_max` <=> 4))))),
  CONSTRAINT `ck_value_range` CHECK (((`value_min` is null) or (`value_max` is null) or (`param_value` between `value_min` and `value_max`)))
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='VQMS 判定整定参数';
