INSERT INTO `vqms_judge_param` VALUES (1,'t_fast',4,'快速性档窗口(分钟)','快速性档扫描窗口 [1, t_fast]，整数可整定',1,4,'0','','2026-09-02 14:34:51','','2026-09-03 11:59:00',NULL),(2,'t_econ',5,'经济性档窗口上限(分钟)','写死=5（指令 5 分钟间隔），锁定不可改',5,5,'0','','2026-09-02 14:34:51','','2026-09-02 14:34:51',NULL),(3,'tier_threshold_fast',1,'快速性档分档阈值(分钟)','外部依据待确认（附件6 无 5 分钟分档条款）',1,1,'0','','2026-09-02 14:34:51','','2026-09-03 13:06:55',NULL),(4,'tier_threshold_econ',5,'经济性档分档阈值(分钟)','外部依据待确认（附件6 无 5 分钟分档条款）',5,5,'0','','2026-09-02 14:34:51','','2026-09-03 13:06:55',NULL),(5,'exempt_q_tol_kvar',2000,'设备级免考顶满容差(kvar)','设备Q距极限≤该值视为顶满（附件6§三无ε规定，现场整定）',0,100000,'0','','2026-09-03 10:16:27','','2026-09-03 10:16:27',NULL),(6,'min_window_completeness_pct',50,'档窗口最低完整度(%)','completeness低于该值的档判INVALID不硬判（数据公平性：缺数窗不罚电厂；1.0数据不可用策略A3/A4最小口径，0=关闭）',0,100,'0','','2026-09-03 11:29:42','','2026-09-03 11:29:42',NULL);
